-- Additive migration: old readers keep working; private board grants remain revoked.
alter table public.reference_countries add column if not exists active boolean not null default true;
alter table public.reference_cities add column if not exists active boolean not null default true;
update public.reference_imports set
  source_url = coalesce(source_url, case source when 'mledoze/countries snapshot' then 'https://github.com/mledoze/countries' when 'GeoNames cities15000 snapshot' then 'https://download.geonames.org/export/dump/cities15000.zip' end),
  license = coalesce(license, case source when 'mledoze/countries snapshot' then 'ODbL-1.0' when 'GeoNames cities15000 snapshot' then 'CC-BY-4.0' end),
  content_hash = coalesce(content_hash, source_version)
where source in ('mledoze/countries snapshot', 'GeoNames cities15000 snapshot');

create or replace function public.sync_reference_snapshot(
  countries_snapshot jsonb, cities_snapshot jsonb, countries_hash text, cities_hash text,
  snapshot_generated_at timestamptz default null
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  country_changed boolean;
  city_changed boolean;
begin
  if countries_snapshot is null or cities_snapshot is null or countries_hash is null or cities_hash is null
     or jsonb_typeof(countries_snapshot) <> 'array' or jsonb_array_length(countries_snapshot) = 0
     or jsonb_typeof(cities_snapshot) <> 'array' or jsonb_array_length(cities_snapshot) = 0
     or countries_hash !~ '^[a-f0-9]{64}$' or cities_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid reference snapshot';
  end if;
  perform pg_advisory_xact_lock(hashtext('advert-reference-snapshot-sync'));
  country_changed := countries_hash is distinct from (select coalesce(content_hash,source_version) from public.reference_imports where source='mledoze/countries snapshot' order by imported_at desc limit 1);
  city_changed := cities_hash is distinct from (select coalesce(content_hash,source_version) from public.reference_imports where source='GeoNames cities15000 snapshot' order by imported_at desc limit 1);

  if country_changed then
    update public.reference_countries set active=false;
    insert into public.reference_countries(code,alpha3,numeric_code,name,official_name,capital,latitude,longitude,subregion,calling_code,population,default_timezone,primary_market,source_payload,active)
    select r->>'code',r->>'alpha3',nullif(r->>'numeric',''),r->>'name',r->>'officialName',r->>'capital',(r->>'lat')::numeric,(r->>'lng')::numeric,r->>'subregion',r->>'callingCode',(r->>'population')::bigint,r->>'timezone',(r->>'primary')::boolean,r,true from jsonb_array_elements(countries_snapshot) r
    on conflict(code) do update set alpha3=excluded.alpha3,numeric_code=excluded.numeric_code,name=excluded.name,official_name=excluded.official_name,capital=excluded.capital,latitude=excluded.latitude,longitude=excluded.longitude,subregion=excluded.subregion,calling_code=excluded.calling_code,population=excluded.population,default_timezone=excluded.default_timezone,primary_market=excluded.primary_market,source_payload=excluded.source_payload,active=true;
    insert into public.reference_currencies(code,name,symbol)
    select distinct on (c->>'code') c->>'code',c->>'name',c->>'symbol' from jsonb_array_elements(countries_snapshot) r cross join lateral jsonb_array_elements(r->'currencies') c
    on conflict(code) do update set name=excluded.name,symbol=excluded.symbol;
    insert into public.reference_languages(code,name)
    select distinct on (l->>'code') l->>'code',l->>'name' from jsonb_array_elements(countries_snapshot) r cross join lateral jsonb_array_elements(r->'languages') l
    on conflict(code) do update set name=excluded.name;
    -- Keep historical tender relationships valid for existing listings.
    insert into public.reference_country_currencies(country_code,currency_code)
    select r->>'code',c->>'code' from jsonb_array_elements(countries_snapshot) r cross join lateral jsonb_array_elements(r->'currencies') c on conflict do nothing;

    insert into public.reference_country_languages(country_code,language_code)
    select r->>'code',l->>'code' from jsonb_array_elements(countries_snapshot) r cross join lateral jsonb_array_elements(r->'languages') l on conflict do nothing;
  end if;
  if country_changed or city_changed then
    insert into public.reference_timezones(tzid)
    select distinct r->>'timezone' from jsonb_array_elements(countries_snapshot) r
    union select distinct r->>'tz' from jsonb_array_elements(cities_snapshot) r
    on conflict(tzid) do nothing;
  end if;
  if city_changed then
    update public.reference_cities set active=false;
    insert into public.reference_cities(geoname_id,country_code,name,latitude,longitude,population,timezone,active)
    select (r->>'id')::bigint,r->>'country',r->>'name',(r->>'lat')::numeric,(r->>'lng')::numeric,(r->>'pop')::bigint,r->>'tz',true from jsonb_array_elements(cities_snapshot) r
    on conflict(geoname_id) do update set country_code=excluded.country_code,name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,population=excluded.population,timezone=excluded.timezone,active=true;
  end if;
  if country_changed then
    insert into public.reference_imports(source,source_version,content_hash,source_url,license,generated_at,record_count)
    values('mledoze/countries snapshot',countries_hash,countries_hash,'https://github.com/mledoze/countries','ODbL-1.0',snapshot_generated_at,jsonb_array_length(countries_snapshot));
  end if;
  if city_changed then
    insert into public.reference_imports(source,source_version,content_hash,source_url,license,generated_at,record_count)
    values('GeoNames cities15000 snapshot',cities_hash,cities_hash,'https://download.geonames.org/export/dump/cities15000.zip','CC-BY-4.0',snapshot_generated_at,jsonb_array_length(cities_snapshot));
  end if;
  return jsonb_build_object('countries',case when country_changed then jsonb_array_length(countries_snapshot) else 0 end,'cities',case when city_changed then jsonb_array_length(cities_snapshot) else 0 end);
end $$;
revoke all on function public.sync_reference_snapshot(jsonb,jsonb,text,text,timestamptz) from public,anon,authenticated;
grant execute on function public.sync_reference_snapshot(jsonb,jsonb,text,text,timestamptz) to service_role;

