s":["stock:included","stock:not-included","stock:negotiable"]}}},"agriculture":{"machinery":{"machine":{"required":true,"options":null},"year":{"required":false,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used"]}},"land":{"size":{"required":true,"options":null},"title":{"required":true,"options":["title:title-deed","title:offer-letter","title:still-confirming"]},"use":{"required":false,"options":null}},"produce":{"crop":{"required":true,"options":null},"pack":{"required":true,"options":null}}},"livestock":{"cattle":{"animal":{"required":true,"options":null},"count":{"required":true,"options":null},"detail":{"required":false,"options":null}},"goats":{"animal":{"required":true,"options":null},"count":{"required":true,"options":null},"detail":{"required":false,"options":null}},"poultry":{"animal":{"required":true,"options":null},"count":{"required":true,"options":null},"detail":{"required":false,"options":null}},"pigs":{"animal":{"required":true,"options":null},"count":{"required":true,"options":null},"detail":{"required":false,"options":null}},"fish":{"animal":{"required":true,"options":null},"count":{"required":true,"options":null},"detail":{"required":false,"options":null}},"other":{"animal":{"required":true,"options":null},"count":{"required":true,"options":null},"detail":{"required":false,"options":null}}},"pets":{"dogs":{"breed":{"required":true,"options":null},"age":{"required":true,"options":null},"sex":{"required":true,"options":["sex:male","sex:female"]}},"cats":{"breed":{"required":true,"options":null},"age":{"required":true,"options":null},"sex":{"required":true,"options":["sex:male","sex:female","sex:mixed"]}},"birds":{"breed":{"required":true,"options":null},"count":{"required":true,"options":null}}},"babies":{"kids-clothes":{"age":{"required":true,"options":null},"item":{"required":true,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used"]}},"gear":{"item":{"required":true,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used"]}},"school":{"item":{"required":true,"options":null},"level":{"required":true,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used"]}}},"fashion":{"clothing":{"item":{"required":true,"options":null},"sizes":{"required":true,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used","condition:bulk-unchecked"]}},"fabric":{"fabric":{"required":true,"options":null},"length":{"required":true,"options":null}},"shoes":{"item":{"required":true,"options":null},"sizes":{"required":true,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used"]}}},"health":{"space":{"use":{"required":true,"options":null},"size":{"required":false,"options":null}},"care":{"service":{"required":true,"options":null},"who":{"required":true,"options":null}},"pharmacy":{"stock":{"required":true,"options":null},"condition":{"required":true,"options":["condition:sealed","condition:short-dated","condition:mixed"]}},"equipment":{"item":{"required":true,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used"]}}},"education":{"materials":{"level":{"required":true,"options":null},"subject":{"required":false,"options":null},"condition":{"required":true,"options":["condition:new","condition:like-new","condition:used"]}},"lessons":{"subject":{"required":true,"options":null},"level":{"required":true,"options":null},"format":{"required":true,"options":["format:at-my-place","format:at-the-student-s-home","format:online"]}}},"community":{"venues":{"space":{"required":true,"options":null},"capacity":{"required":true,"options":null}},"goods":{"item":{"required":true,"options":null},"quantity":{"required":true,"options":null},"condition":{"required":false,"options":["condition:new","condition:like-new","condition:used"]}}}}'::jsonb;
  fields jsonb;
  field record;
  value text;
begin
  fields := catalog #> array[item->>'category',item->>'subcategory'];
  if fields is null or jsonb_typeof(item->'details') is distinct from 'object' then return false; end if;
  for field in select entry.key,entry.value as definition from jsonb_each(item->'details') as entry loop
    if not (fields ? field.key) or jsonb_typeof(field.definition) <> 'string' or length(field.definition #>> '{}') > 80 then return false; end if;
  end loop;
  -- Versionless rows retain legacy label compatibility until their next edit.
  if not (item ? 'taxonomyVersion') then return true; end if;
  if jsonb_typeof(item->'taxonomyVersion') is distinct from 'number' then return false; end if;
  if item->>'taxonomyVersion' <> '1' then return false; end if;
  for field in select entry.key,entry.value as definition from jsonb_each(fields) as entry loop
    value := item->'details'->>field.key;
    if field.definition->>'required'='true' and coalesce(length(trim(value)),0)=0 then return false; end if;
    if value is not null and field.definition->'options' <> 'null'::jsonb and not ((field.definition->'options') ? value) then return false; end if;
  end loop;
  return true;
end $contract$;
revoke all on function public.listing_taxonomy_valid(jsonb) from public,anon,authenticated;
grant execute on function public.listing_taxonomy_valid(jsonb) to service_role;

alter table public.board_listings add constraint board_listings_payload_contract check (coalesce(
  jsonb_typeof(payload)='object'
  and jsonb_typeof(payload->'title')='string'
  and jsonb_typeof(payload->'description')='string'
  and jsonb_typeof(payload->'city')='string'
  and jsonb_typeof(payload->'locationDetail')='string'
  and jsonb_typeof(payload->'country')='string' and payload->>'country' ~ '^[A-Z]{2}$'
  and jsonb_typeof(payload->'currency')='string' and payload->>'currency' ~ '^[A-Z]{3}$'
  and (not (payload ? 'locationPrecision') or payload->>'locationPrecision' in ('city','specific'))
  and public.listing_taxonomy_valid(payload)
  and case when jsonb_typeof(payload->'price')='number' then
    (payload->>'price')::numeric > 0 and (payload->>'price')::numeric <= 999999999
    and (payload->>'price')::numeric = trunc((payload->>'price')::numeric) else false end
  and coalesce(length(payload->>'title'),0) between 4 and 80
  and coalesce(length(payload->>'description'),0) between 20 and 2000
  and coalesce(length(payload->>'city'),0) between 2 and 80
  and coalesce(length(payload->>'locationDetail'),0) between 2 and 120
  and ((not (payload ? 'latitude') and not (payload ? 'longitude') and coalesce(payload->>'locationPrecision','city') <> 'specific')
    or (jsonb_typeof(payload->'latitude')='number' and jsonb_typeof(payload->'longitude')='number'
      and (payload->>'latitude')::numeric between -90 and 90 and (payload->>'longitude')::numeric between -180 and 180))
  and (not (payload ? 'images') or case when jsonb_typeof(payload->'images')='array' then jsonb_array_length(payload->'images') <= 6 else false end)
, false)) not valid;
-- Existing rows are not rewritten. Validation is a separate deployment verification.
comment on constraint board_listings_payload_contract on public.board_listings is 'Taxonomy v1 6bd706790d5c1ffcdf863fbe49e86d9ebcadf4f02f4eaf2feefa797264fcf47e; whole-unit prices, public specific-location text, bounded coordinates and media.';

alter table public.board_listings
  add column if not exists country_code text generated always as (payload->>'country') stored,
  add column if not exists currency_code text generated always as (payload->>'currency') stored;
alter table public.board_listings add constraint board_listings_country_currency_fk
